-- =============================================================================
-- Studuel — Migration 307 : FRANÇAIS 5e — LE PROGRAMME COMPLET (13 fiches)
--
-- ⚠️ FICHIER GÉNÉRÉ — ne pas éditer à la main.
--    Source : scripts/contenu/*.mjs
--    Regénérer : node scripts/seed-contenu.mjs --num 307 --modules francais-5e
--
-- CONSTAT : le français de 5e n'avait que les 5 fiches du premier jeu de données de
-- l'app — « Le roman de chevalerie », « Voyages et découvertes », « Théâtre : la
-- comédie », « Les compléments de phrase », « Conjugaison : passé simple ». Un
-- élève de 5e qui révisait les récits de voyage, la poésie de l'ailleurs, le roman
-- d'aventures, L'École des femmes, les récits d'enfance, le conte merveilleux,
-- l'utopie, la dystopie, les héros médiévaux et antiques ou le rapport de l'homme à
-- la nature ne trouvait RIEN. Cette migration installe les 13 fiches, rangées sous
-- les 5 chapitres de la maquette — les quatre questionnements du BO plus un
-- questionnement complémentaire — et retire les 5 fiches génériques.
-- DEUX DES CINQ FICHES RETIRÉES SONT DES POINTS DE LANGUE (« Les compléments de
-- phrase », « Conjugaison : passé simple ») : la grammaire a son propre rayon en
-- Première (migration 259) et le collège n'en a pas encore ; les laisser au milieu
-- des œuvres brouillerait le dossier.
--
-- Cette migration apporte : 13 chapitres, 13 leçons,
-- 13 quiz et 104 questions, sur 1 matière.
--
-- CHOIX ASSUMÉS :
--  · tous les quiz sont `is_free = true`. Aucun compte ne peut aujourd’hui
--    passer `tier1` (aucun paiement n’existe), donc un quiz payant serait un
--    quiz INVISIBLE pour 100 % des élèves — le contraire du but ;
--  · chaque cours porte des sections `##`, ce qui rend sa carte mentale
--    dérivable (cf. lib/mind-map-auto) : aucune tuile ne promet dans le vide.
--
-- Idempotent : les UUID sont dérivés du contenu (SHA-1), donc stables ; les
-- INSERT sont tous gardés par ON CONFLICT DO NOTHING. Rejouable sans risque.
--
-- PRÉREQUIS : 002, 008, 191, 193 exécutées (les matières doivent exister).
-- À exécuter dans : Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

-- 0. Ménage ----------------------------------------------------------------
-- [francais] La colonne chapters.theme (migration 234) conditionne tout ce qui suit : ce
-- [francais] module range ses 13 fiches sous 5 chapitres, et l'INSERT écrit la colonne. Elle
-- [francais] est REPRISE ici en ADD COLUMN IF NOT EXISTS parce qu'on ne peut pas garantir que
-- [francais] la 234 soit passée en production — sans cette reprise, la migration échouerait
-- [francais] sur "column chapters.theme does not exist", les 5 anciens chapitres déjà
-- [francais] supprimés et les 13 neufs pas encore posés : une matière vide.
-- [francais] Le ménage qui suit LIT cette colonne : elle doit exister avant lui.
-- [francais] Le GRANT n'est pas décoratif : la migration 182 a révoqué le SELECT de table sur
-- [francais] chapters (pour cacher mind_map) et ne l'a rendu que colonne par colonne.
ALTER TABLE public.chapters ADD COLUMN IF NOT EXISTS theme TEXT;
GRANT SELECT (theme) ON public.chapters TO anon;
GRANT SELECT (theme) ON public.chapters TO authenticated;

-- [francais] Les 5 chapitres hérités de la 008 partent, au niveau 5e SEULEMENT.
-- [francais] 
-- [francais] LE REPÈRE EST theme IS NULL, PAS LE TITRE : « Théâtre : la comédie » et
-- [francais] « Voyages et découvertes » recouvrent des entrées que le programme neuf traite
-- [francais] sous d'autres titres, et un DELETE par titre demanderait de vérifier à chaque
-- [francais] relecture qu'aucune fiche neuve ne les reprend exactement. Le critère « pas de
-- [francais] chapitre de programme » vise exactement les cinq lignes voulues : elles datent de
-- [francais] la 008, bien avant la colonne theme, tandis que les 13 fiches neuves en portent
-- [francais] une dès l'INSERT — le ménage tourne AVANT les insertions et ne peut donc jamais
-- [francais] mordre sur elles, ni au premier passage ni au rejeu.
-- [francais] Le filtre level = '5e' est indispensable : le français existe sur six niveaux, et
-- [francais] la 4e comme la 3e sont traitées par leurs propres migrations.
-- [francais] L'ordre compte : la file "À revoir" d'abord (review_items.item_id n'a PAS de clé
-- [francais] étrangère), puis les quiz (quizzes.lesson_id est ON DELETE SET NULL), puis les
-- [francais] chapitres, dont les leçons partent en cascade.
DELETE FROM public.review_items ri
 USING public.quiz_questions qq, public.quizzes qz, public.lessons l,
       public.chapters c, public.subjects s
 WHERE ri.item_kind = 'question'
   AND ri.item_id = qq.id
   AND qq.quiz_id = qz.id
   AND qz.lesson_id = l.id
   AND l.chapter_id = c.id
   AND c.subject_id = s.id
   AND s.slug = 'francais'
   AND c.level = '5e'
   AND c.theme IS NULL;

DELETE FROM public.quizzes q
 USING public.lessons l, public.chapters c, public.subjects s
 WHERE q.lesson_id = l.id
   AND l.chapter_id = c.id
   AND c.subject_id = s.id
   AND s.slug = 'francais'
   AND c.level = '5e'
   AND c.theme IS NULL;

DELETE FROM public.chapters c
 USING public.subjects s
 WHERE c.subject_id = s.id
   AND s.slug = 'francais'
   AND c.level = '5e'
   AND c.theme IS NULL;

