-- 1 bis. Axes du programme -------------------------------------------------
-- `chapters.theme` (migration 234) : l’intitulé du programme officiel qui
-- coiffe le chapitre. La page matière s’en sert pour grouper au lieu
-- d’aligner 28 lignes à plat. UPDATE et non INSERT : le chapitre peut déjà
-- exister (l’INSERT précédent l’aurait alors ignoré).
UPDATE public.chapters c SET theme = v.theme
  FROM (VALUES
    ('8f784bec-0277-5d05-b70e-7d47fb81e7bc'::uuid, 'Se chercher, se construire — Le voyage et l’aventure : pourquoi aller vers l’inconnu ?'),
    ('4366ab9b-8872-567d-bf24-2f2eb9c1a9ea'::uuid, 'Se chercher, se construire — Le voyage et l’aventure : pourquoi aller vers l’inconnu ?'),
    ('6c916708-6b4d-586a-bacf-4aaff6a2264f'::uuid, 'Se chercher, se construire — Le voyage et l’aventure : pourquoi aller vers l’inconnu ?'),
    ('fde4fddf-3208-557a-829e-0de6fa170325'::uuid, 'Vivre en société, participer à la société — Avec autrui : famille, amis, réseaux'),
    ('6599efec-fefb-5c60-86a9-b028fa4f86ed'::uuid, 'Vivre en société, participer à la société — Avec autrui : famille, amis, réseaux'),
    ('3a7a28dd-117c-5eac-9606-4dc594d578b4'::uuid, 'Regarder le monde, inventer des mondes — Imaginer des univers nouveaux'),
    ('c841f7b9-62c1-579c-9266-06e8246818e5'::uuid, 'Regarder le monde, inventer des mondes — Imaginer des univers nouveaux'),
    ('6b657546-53d8-51cd-8eaf-0b914516971f'::uuid, 'Regarder le monde, inventer des mondes — Imaginer des univers nouveaux'),
    ('a4a0a655-c66d-5180-9dba-7afc5b3d5891'::uuid, 'Agir sur le monde — Héros / héroïnes et héroïsme'),
    ('01669d26-296b-5577-bdc5-f80eaba6227d'::uuid, 'Agir sur le monde — Héros / héroïnes et héroïsme'),
    ('6a380608-689d-5a2d-b67e-70358a89b0d7'::uuid, 'Questionnements complémentaires — L’être humain est-il maître de la nature ?'),
    ('f4b8a80c-f446-52cc-b212-3153a99aa0ac'::uuid, 'Questionnements complémentaires — L’être humain est-il maître de la nature ?'),
